import{Lt as e,Z as t,_t as n,vt as r}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";var i=JSON.parse(`{"title":"Zotero 中文社区 - 新的征程","description":"","frontmatter":{"title":"Zotero 中文社区 - 新的征程","date":"2024-8-1"},"headers":[],"relativePath":"blog/posts/new-beginning.md","filePath":"blog/blog-repo/posts/new-beginning.md"}`),a={name:`blog/posts/new-beginning.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /blog/posts/new-beginning.md for this page in Markdown format</div><h1 id="zotero-中文社区-新的征程" tabindex="-1">Zotero 中文社区 - 新的征程 <a class="header-anchor" href="#zotero-中文社区-新的征程" aria-label="Permalink to “Zotero 中文社区 - 新的征程”">​</a></h1><p>在过去的一段时间，我们在众多志愿者地帮助下，购买了域名 <code>zotero-chinese.com</code>，构建了网站，整合了很多 Zotero 相关的文档、资源，我们非常高兴地宣布，Zotero 中文社区进入了一个全新的阶段！</p><h2 id="过去" tabindex="-1">过去 <a class="header-anchor" href="#过去" aria-label="Permalink to “过去”">​</a></h2><p>过去一年，Zotero 中文社区在大家的支持下，取得了许多令人振奋的成果。</p><p>根据不完全统计，中文社区网站日均访问近万人次，其中大陆同学占比约 80%，港澳台同学占比约 10%。</p><h3 id="🇨🇳-zotero-的汉化" tabindex="-1">🇨🇳 Zotero 的汉化 <a class="header-anchor" href="#🇨🇳-zotero-的汉化" aria-label="Permalink to “🇨🇳 Zotero 的汉化”">​</a></h3><p><img src="/assets/zotero-transifex.CYHpy4--.png" alt="Zotero 本地化" width="2880" height="1459"></p><p>Zotero 中文社区一直积极参与 Zotero 的本地化翻译工作，通过 Transifex 平台，我们和其他翻译员共同为 Zotero 提供了完整的中文翻译，确保中文用户能够无障碍地使用和理解 Zotero 的各项功能。</p><h3 id="📖-zotero-百科全书" tabindex="-1">📖 Zotero 百科全书 <a class="header-anchor" href="#📖-zotero-百科全书" aria-label="Permalink to “📖 Zotero 百科全书”">​</a></h3><p><img src="/assets/zotero-wiki.BkauIrav.png" alt="Zotero 百科全书" width="2846" height="1462"></p><p>我们对中文用户手册进行了全面更新，涵盖了 Zotero 的基础操作、插件使用，以及常见问题的解决方案，帮助了众多中文用户顺利上手并解决了使用中的困惑。</p><p>在此，感谢所有为文档编辑做出贡献的同学！</p><p><img src="https://cdn.jsdelivr.net/gh/zotero-chinese/.github@main/.github-contributors/zotero-chinese_wiki.svg" alt="Zotero wiki 仓库贡献者"></p><h3 id="🛠️-插件商店页面" tabindex="-1">🛠️ 插件商店页面 <a class="header-anchor" href="#🛠️-插件商店页面" aria-label="Permalink to “🛠️ 插件商店页面”">​</a></h3><p><img src="/assets/zotero-plugins-market.vUizxajd.png" alt="Zotero 插件商店" width="2846" height="1462"></p><p>我们全新推出了插件商店页面，收录了大部分实用的 Zotero 插件，并且支持按功能、兼容性等多维度进行搜索、筛选和排序。页面还提供了多个下载镜像，方便国内用户快捷获取所需插件。</p><p>从去年九月起，到目前为止，插件商店页面已经服务近 73 万次，平均每天有两千余位同学使用插件商店页面，且在稳步上涨。</p><p>插件商店页面由 <a href="https://northword.cn" target="_blank" rel="noreferrer">@northword</a> 创建，感谢 <a href="https://github.com/l0o0" target="_blank" rel="noreferrer">@l0o0</a> 创建的表格格式的插件商店页面。</p><p>特别感谢 <a href="https://github.com/volatile-static" target="_blank" rel="noreferrer">@volatile-static</a> 维护的「插件排行榜」。</p><h3 id="🔄-转换器列表页面" tabindex="-1">🔄 转换器列表页面 <a class="header-anchor" href="#🔄-转换器列表页面" aria-label="Permalink to “🔄 转换器列表页面”">​</a></h3><p><img src="/assets/zotero-translators.CczyNEgG.png" alt="Zotero 转换器页面" width="2846" height="1462"></p><p>为了提方便同学们查询 Zotero 可以抓取哪些中文网站，我们推出了转换器列表页面。</p><p>这个页面列出了由中文社区维护的 Zotero 转换器，帮助用户了解 Zotero 支持抓取哪些中文网站，并极大地提高了文献管理的效率。</p><p>特别感谢 <a href="https://github.com/jiaojiaodubai" target="_blank" rel="noreferrer">@jiaojiaodubai</a> 和 <a href="https://github.com/l0o0" target="_blank" rel="noreferrer">@l0o0</a> 对转换器维护做出的贡献！</p><p>感谢 <a href="https://github.com/jiaojiaodubai" target="_blank" rel="noreferrer">@jiaojiaodubai</a> 对转换器页面的重大优化。</p><h3 id="📑-中文-csl-页面" tabindex="-1">📑 中文 CSL 页面 <a class="header-anchor" href="#📑-中文-csl-页面" aria-label="Permalink to “📑 中文 CSL 页面”">​</a></h3><p><img src="/assets/zotero-csl.BPOfzjGK.png" alt="中文 CSL 页面" width="2846" height="1462"></p><p>我们还推出了支持中英双语排版的 CSL 样式页面，包含了包括国标及其变种样式在内的多种格式，并涵盖部分国内高校硕博论文、学术期刊的参考文献格式，为广大中文用户提供了更丰富的样式选择。</p><p>特别感谢 <a href="https://github.com/zepinglee" target="_blank" rel="noreferrer">@zepinglee</a> 和 <a href="https://github.com/redleafnew" target="_blank" rel="noreferrer">@redleafnew</a> 对中文 CSL 维护做出的贡献！</p><h2 id="未来" tabindex="-1">未来 <a class="header-anchor" href="#未来" aria-label="Permalink to “未来”">​</a></h2><p>感谢每一位社区成员的支持与贡献！</p><p>Zotero 中文社区是我们共同努力的成果，期待在未来的日子里，继续与大家一起探索和推动 Zotero 在中文用户中的发展。让我们一同迎接 Zotero 带来的全新体验！🎉🚀</p>`,33)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};